<?php namespace App\Http\Controllers; use App\Repositories\Contracts\ProductRepository; use App\Models\Vendor; use Illuminate\Http\Request; class StorefrontController extends Controller { public function home(ProductRepository $products){return view('storefront.home',['products'=>$products->search(['per_page'=>8])]);} public function catalogue(Request $r,ProductRepository $products){return view('storefront.catalogue',['products'=>$products->search($r->all())]);} public function product(string $slug,ProductRepository $products){return view('storefront.product',['product'=>$products->findPublic($slug)]);} public function vendor(string $slug){return view('storefront.vendor',['vendor'=>Vendor::whereSlug($slug)->whereIsApproved(true)->with('products.images','products.inventory')->firstOrFail()]);} }
